(function(w){'use strict';w.DOMPurify={sanitize:function(html){var t=document.createElement('template');t.innerHTML=String(html||'');var bad=t.content.querySelectorAll('script,style,iframe,object,embed,form,base,meta,link');bad.forEach(function(n){n.remove()});t.content.querySelectorAll('*').forEach(function(el){Array.from(el.attributes).forEach(function(a){var n=a.name.toLowerCase(),v=a.value.trim().toLowerCase();if(n.indexOf('on')===0||((n==='href'||n==='src'||n==='xlink:href')&&(v.indexOf('javascript:')===0||v.indexOf('data:text/html')===0))){el.removeAttribute(a.name)}})});return t.innerHTML}}})(window);
